"""Generate a test module for a changed file and repair it until pytest passes."""

from __future__ import annotations

from pathlib import Path

from .config import AppConfig
from .llm_client import LlmClient
from .llm_test_code import ValidationError, ask_for_test_code, write_test_code
from .models import PytestResult, SourceAnalysis, TestTarget
from .prompts import build_generate_tests_prompt, build_repair_tests_prompt
from .pytest_runner import run_pytest
from .repo_paths import relative_to_repo


GENERATED_HEADER = (
    "# This file was generated by AI Unit Test Assistant.\n"
    "# Review before committing.\n"
)


def generated_test_path_for(
    source_file: Path, output_dir: Path, repo_root: Path
) -> Path:
    """Name the generated test after the repo-relative source path so two
    sources with the same stem (app/models.py, lib/models.py) cannot collide.
    """
    rel = relative_to_repo(source_file, repo_root) or Path(source_file.name)
    flat_name = "_".join(rel.with_suffix("").parts)
    return output_dir / f"test_{flat_name}_generated.py"


def generate_and_repair_tests(
    llm: LlmClient,
    config: AppConfig,
    analysis: SourceAnalysis,
    targets: list[TestTarget],
    related_tests: dict[Path, str],
) -> tuple[Path, PytestResult]:
    """Write a generated test module, then repair it until pytest passes or the
    repair attempts run out. Returns the test file and the last pytest result.
    """
    generated_path = generated_test_path_for(analysis.file_path, config.output_dir, config.repo_root)
    test_code = ask_for_test_code(llm, *build_generate_tests_prompt(analysis, targets, related_tests))
    write_test_code(generated_path, GENERATED_HEADER, test_code)

    pytest_result = run_pytest(config.repo_root, [generated_path])
    attempts = 0
    while not pytest_result.passed and attempts < config.repair_attempts:
        attempts += 1
        pytest_output = (pytest_result.stdout or "") + "\n" + (pytest_result.stderr or "")
        try:
            test_code = ask_for_test_code(
                llm, *build_repair_tests_prompt(analysis.source_code, test_code, pytest_output)
            )
        except ValidationError:
            break
        write_test_code(generated_path, GENERATED_HEADER, test_code)
        pytest_result = run_pytest(config.repo_root, [generated_path])

    return generated_path, pytest_result
